const s = $('Settings').first().json;
if (!s.booking_form_url) {
  throw new Error('Paste the production URL of the "Booking form" node in Settings > booking_form_url');
}
const sep = s.booking_form_url.includes('?') ? '&' : '?';
// T-105: a row whose email is not one plain address is left out, still accepted, and nothing is sent for it
const plainEmail = e => /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(String(e).trim());
return $input.all()
  .filter(i => i.json.request_id && i.json.email && plainEmail(i.json.email))
  .map(i => ({ json: {
    ...i.json,
    business_name: s.business_name,
    booking_link: s.booking_form_url + sep + 'request_id=' + encodeURIComponent(i.json.request_id),
  }}));

