const f = $('Booking form').first().json;
const row = $input.first().json;
const email = String(f['Email'] || '').trim().toLowerCase();
const valid = !!f.request_id
  && row.request_id === f.request_id
  && row.status === 'booking_sent'
  && String(row.email || '').trim().toLowerCase() === email;
return [{ json: { ...row, valid } }];

// Splits each working day into blocks of job_hours and keeps the blocks with no event in Google Calendar.
const s = $('Settings').first().json;
const tz = s.timezone;
const isBusy = e => e.start && e.status !== 'cancelled' && e.transparency !== 'transparent';
const busy = $input.all().map(i => i.json).filter(isBusy).map(e => ({
  start: DateTime.fromISO(e.start.dateTime || e.start.date, { zone: tz }),
  end: DateTime.fromISO(e.end.dateTime || e.end.date, { zone: tz }),
}));

const days = String(s.work_days).split(',').map(x => Number(x.trim()));
const [sh, sm] = String(s.day_start).split(':').map(Number);
const [eh, em] = String(s.day_end).split(':').map(Number);
const hours = Number(s.job_hours);
const max = Number(s.max_options);
const earliest = DateTime.now().setZone(tz).plus({ hours: Number(s.min_notice_hours) });

const slots = [];
// T-105: a job length that is not a positive number would never advance the loop; offer no times and the owner is told
const hoursOk = Number.isFinite(hours) && hours > 0;
for (let d = 0; hoursOk && d <= Number(s.days_ahead) && slots.length < max; d++) {
  const day = earliest.startOf('day').plus({ days: d });
  if (!days.includes(day.weekday)) continue;
  let t = day.set({ hour: sh, minute: sm || 0 });
  const close = day.set({ hour: eh, minute: em || 0 });
  while (t.plus({ hours }) <= close && slots.length < max) {
    const end = t.plus({ hours });
    if (t >= earliest && !busy.some(b => b.start < end && b.end > t)) {
      slots.push({ start: t.toISO(), end: end.toISO(), label: t.toFormat("ccc d LLL, h:mm a") });
    }
    t = end;
  }
}

return [{ json: {
  slots,
  has_slots: slots.length > 0,
  form_fields: [{
    fieldLabel: 'Available times',
    fieldType: 'dropdown',
    requiredField: true,
    fieldOptions: { values: slots.map(x => ({ option: x.label })) },
  }],
}}];

const pick = $json['Available times'];
const slot = $('Find free times').first().json.slots.find(x => x.label === pick);
if (!slot) throw new Error('This time is not in the list: ' + pick);
const { valid, ...row } = $('Check the link').first().json;
return [{ json: { ...row, ...slot } }];

// Right before booking: the time must still be empty in Calendar and the row must not be booked yet.
const c = $('Read the choice').first().json;
const isBusy = e => e.start && e.status !== 'cancelled' && e.transparency !== 'transparent';
const events = $('Is it still free?').all().map(i => i.json).filter(isBusy);
const row = $input.first().json;
return [{ json: { ...c, free: events.length === 0 && row.status === 'booking_sent' } }];

