const s = $('Settings').first().json;
const tomorrow = DateTime.now().setZone(s.timezone).plus({ days: 1 }).toISODate();
// T-105: with a time zone n8n cannot read, tomorrow is null and so is every job date: nothing is sent
if (!tomorrow) return [];
return $input.all()
  .filter(i => i.json.job_start && i.json.email)
  .filter(i => DateTime.fromISO(String(i.json.job_start), { zone: s.timezone }).toISODate() === tomorrow)
  .map(i => ({ json: {
    ...i.json,
    business_name: s.business_name,
    when: DateTime.fromISO(String(i.json.job_start), { zone: s.timezone }).toFormat("cccc d LLLL, h:mm a"),
  }}));

